def constraintsConsistent(n, constraints):
    parent = list(range(n))
    diff = [0] * n  # diff[x] = value[x] - value[parent[x]]

    def find(x):
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        root = x
        acc = 0
        for node in reversed(path):
            acc += diff[node]
            diff[node] = acc
            parent[node] = root
        return root

    for a, b, d in constraints:
        ra, rb = find(a), find(b)
        if ra == rb:
            if diff[a] - diff[b] != d:
                return False
        else:
            parent[ra] = rb
            diff[ra] = d - diff[a] + diff[b]
    return True
